('554b0093-5de6-5659-b271-2a8e5ef0bae0', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Peyva "dîrok" bi Tirkî çi ye?', 'coğrafya', 'edebiyat', 'müzik', 'tarih', 'D', '"Dîrok" bi Tirkî "tarih" e; tê wateya bûyerên berê û zanista wan. Mînak: "Em dîrokê dixwînin."', '"Dîrok" bi Tirkî "tarih" e; tê wateya bûyerên berê û zanista wan. Mînak: "Em dîrokê dixwînin."', '"Dîrok" Türkçede "tarih" demektir; geçmiş olaylar ve onları inceleyen bilim anlamına gelir. Örnek: "Em dîrokê dixwînin." (Tarih okuyoruz.)', 2, true, 'multiple_choice', NULL, NULL, 'Ferhenga kurdî', 'Zana Farqînî, Ferhenga Kurdî-Tirkî (2004); Michael L. Chyet, Kurdish-English Dictionary (Yale, 2003)', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_dirok_0038
