('b2b9b826-1d36-5cf5-99b2-48d5711a8219', (select id from categories where name = 'Dîrok'), 'ku-kmr', '"bandora çandî" çi ye?', 'bandorkirina civakan li hev', 'ji delîlan wate derxistin', 'rêbaza têgihiştina rabirdûyê bi şahidî û vegotinan', 'veguhastina cih a civakan', 'A', 'Bandora çandî tê wateya ku civak bandorê li hev dikin; mînak ziman, xwarin û muzîk bi têkiliyê derbasî hev dibin.', 'Bandora çandî tê wateya ku civak bandorê li hev dikin; mînak ziman, xwarin û muzîk bi têkiliyê derbasî hev dibin.', 'Kültürel etkileşim toplumların birbirini etkilemesi demektir; örneğin dil, yemek ve müzik temas yoluyla birbirine geçer.', 1, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_7881
