('787bc88a-4690-593a-a07b-6f02a4b7e948', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Rast e an şaş e: "Serhildana Koçgirî" berxwedana derdora Çiyayê Agirî bû ya di navbera salên 1927-1930î de.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Serhildanên Agirî" ye; "Serhildana Koçgirî" serhildana kurdî bû ya sala 1921ê ya li derdora Sêwasê.', 'Na — ev ravekirina "Serhildanên Agirî" ye; "Serhildana Koçgirî" serhildana kurdî bû ya sala 1921ê ya li derdora Sêwasê.', 'Hayır — bu tanım "Serhildanên Agirî" kavramına aittir; "Serhildana Koçgirî" ise 1921''de Sivas yöresinde gelişen Kürt ayaklanmasıydı.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0005
