('3fea5bcd-9186-567e-8c9a-62de16033a94', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Rast e an şaş e: "Komkujiya Helebceyê" êrîşa kîmyayî bû ku di sala 1988an de li dijî kurdan hat kirin.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Komkujiya Helebceyê êrîşeke bi çekên kîmyayî bû li dijî sivîlan; di sala 1988an de li Helebceyê pêk hat.', 'Rast e. Komkujiya Helebceyê êrîşeke bi çekên kîmyayî bû li dijî sivîlan; di sala 1988an de li Helebceyê pêk hat.', 'Doğru. Halepçe Katliamı sivillere karşı kimyasal silahlarla yapılan bir saldırıydı; 1988''de Halepçe''de gerçekleşti.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0008
('d9ae733b-8ba3-5d16-85ae-782e64caa70c', (select id from categories where name = 'Dîrok'), 'ku-kmr', '"Peymana Qesrişîrînê" peymana 1639an bû ku erdnîgariya kurdî di navbera du împaratoriyan de par kir. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Peymana Qesrişîrînê di sala 1639an de di navbera Osmaniyan û Sefewiyan de hat çêkirin û sînorê di navbera wan de diyar kir.', 'Rast e. Peymana Qesrişîrînê di sala 1639an de di navbera Osmaniyan û Sefewiyan de hat çêkirin û sînorê di navbera wan de diyar kir.', 'Doğru. Kasrışirin Antlaşması 1639''da Osmanlılar ile Safeviler arasında yapılmış ve aralarındaki sınırı belirlemiştir.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0010
('15753b05-5b6d-5d79-80a2-790581e8382e', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Rast e an şaş e: "Komara Mehabadê" komareke kurdî ya kurtedem bû ku di sala 1946an de li rojhilat hat avakirin.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Komara Mehabadê li Mehabadê hat avakirin û temenê wê pir kurt bû; ew li rojhilat rêveberiyeke bi vî navî bû.', 'Rast e. Komara Mehabadê li Mehabadê hat avakirin û temenê wê pir kurt bû; ew li rojhilat rêveberiyeke bi vî navî bû.', 'Doğru. Mahabad Cumhuriyeti merkezi Mahabad olmak üzere kurulmuş ve çok kısa ömürlü olmuştur; doğuda bu adla bilinen yönetimdir.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0012
('aa3da0a8-ed8f-52d6-95f5-dd2ffc9c98ed', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Rast e an şaş e: "Qazî Mihemed" serokê Komara Mehabadê bû ku piştî hilweşandina wê hat îdamkirin.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Qazî Mihemed serokê Komara Mehabadê bû û piştî hilweşandina komarê ew hat îdamkirin.', 'Rast e. Qazî Mihemed serokê Komara Mehabadê bû û piştî hilweşandina komarê ew hat îdamkirin.', 'Doğru. Kadı Muhammed Mahabad Cumhuriyeti''nin lideriydi ve cumhuriyetin yıkılmasından sonra idam edildi.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0014
('eb159129-2f7d-53ff-b121-6fa5f3640d8a', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Rast e an şaş e: "Qazî Mihemed" serokê serhildana 1925an bû li bakurê Kurdistanê.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Şêx Seîd" e; "Qazî Mihemed" serokê Komara Mehabadê bû ku piştî hilweşandina wê hat îdamkirin.', 'Na — ev ravekirina "Şêx Seîd" e; "Qazî Mihemed" serokê Komara Mehabadê bû ku piştî hilweşandina wê hat îdamkirin.', 'Hayır — bu tanım "Şêx Seîd" kavramına aittir; "Qazî Mihemed" ise Mehabad Cumhuriyeti''nin yıkılışından sonra idam edilen lideriydi.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0015
('1a73264f-3cb5-5811-ac9f-61af4f52a994', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Rast e an şaş e: "Şêx Seîd" serokê serhildana 1925an bû li bakurê Kurdistanê.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Şêx Seîd pêşengê serhildana 1925an e ku li bakur belav bû û navê xwe ji wî digire.', 'Rast e. Şêx Seîd pêşengê serhildana 1925an e ku li bakur belav bû û navê xwe ji wî digire.', 'Doğru. Şeyh Said, kuzeyde yayılan 1925 ayaklanmasının önderidir ve ayaklanma onun adıyla anılır.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0016
