('20c1fc22-f609-5a08-9972-e3917f62bd56', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Mistefa Barzanî serokê tevgera neteweyî ya başûr bû ku bi dehsalan berdewam kir. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Mistefa Barzanî bi dehsalan pêşengiya tevgera başûr kir û wekî rêberekî wê tevgerê tê naskirin.', 'Rast e. Mistefa Barzanî bi dehsalan pêşengiya tevgera başûr kir û wekî rêberekî wê tevgerê tê naskirin.', 'Doğru. Mustafa Barzani güneydeki harekete onlarca yıl önderlik etmiş ve bu hareketin önderi olarak tanınır.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0018
('741094d1-57e6-5a3b-927f-78e3865866e0', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Mistefa Barzanî ew mîrê Botan bû ku di sedsala 19an de li dijî navendîkirinê rabû. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina Bedirxan Beg e; Mistefa Barzanî serokê tevgera neteweyî ya başûr e ya ku bi dehsalan berdewam kir.', 'Na — ev ravekirina Bedirxan Beg e; Mistefa Barzanî serokê tevgera neteweyî ya başûr e ya ku bi dehsalan berdewam kir.', 'Hayır — bu tanım Bedirxan Beg''e aittir; Mistefa Barzanî, güneyde onlarca yıl süren ulusal hareketin önderidir.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0019
('4769ede5-119e-509a-8959-c9a906fbc599', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Rast e an şaş e: Bedirxan Beg ew mîrê Botan bû ku di sedsala 19an de li dijî navendîkirinê rabû.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Bedirxan Beg mîrê Botan bû bi navenda Cizîrê û di sedsala 19an de li dijî polîtîkaya navendîkirinê rabû.', 'Rast e. Bedirxan Beg mîrê Botan bû bi navenda Cizîrê û di sedsala 19an de li dijî polîtîkaya navendîkirinê rabû.', 'Doğru. Bedirhan Bey merkezi Cizre olan Botan beyiydi ve 19. yüzyılda merkezileştirme politikasına karşı ayaklandı.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0020
('843108f0-34f2-5bb7-b7f7-3232ef825579', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Rast e an şaş e: Bedirxan Beg ew kes bû ku di sala 1898an de rojnameya kurdî ya yekem derxist.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina Mîqdat Mîdhad Bedirxan e; Bedirxan Beg ew mîrê Botan bû ku di sedsala 19an de li dijî navendîkirinê rabû.', 'Na — ev ravekirina Mîqdat Mîdhad Bedirxan e; Bedirxan Beg ew mîrê Botan bû ku di sedsala 19an de li dijî navendîkirinê rabû.', 'Hayır — bu tanım Mîqdat Mîdhad Bedirxan''a aittir; Bedirxan Beg, 19. yüzyılda merkezileşmeye karşı ayaklanan Botan beyidir.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0021
('c3b5403c-eb4c-513f-ac64-26d92c2f7b37', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Rast e an şaş e: Mîqdad Mîdhad Bedirxan ew kes bû ku di sala 1898an de rojnameya kurdî ya yekem derxist.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Mîqdad Mîdhad Bedirxan yekemîn rojnameya kurdî, Kurdistan, derxist û ev rojname li Qahîreyê hat weşandin.', 'Rast e. Mîqdad Mîdhad Bedirxan yekemîn rojnameya kurdî, Kurdistan, derxist û ev rojname li Qahîreyê hat weşandin.', 'Doğru. Mikdat Mithat Bedirhan ilk Kürt gazetesi Kürdistan''ı çıkarmış ve bu gazete Kahire''de yayımlanmıştır.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0022
('b6381e5b-24a9-531c-ae0a-a245c140992b', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Rast e an şaş e: Dîroka devkî veguhastina bûyerên rabirdûyê ye bi rêya şahidî û çîrokên devkî.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Dîroka devkî xwe dispêre bîranîn û vegotinên mirovan; ew bi hevpeyvîn û çîrokên devkî rabirdûyê diparêze.', 'Rast e. Dîroka devkî xwe dispêre bîranîn û vegotinên mirovan; ew bi hevpeyvîn û çîrokên devkî rabirdûyê diparêze.', 'Doğru. Sözlü tarih insanların hatırlama ve anlatılarına dayanır; görüşmeler ve sözlü hikâyelerle geçmişi korur.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0024
('fafdc2a6-81a2-518e-81ba-2aaa93b484bc', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Rast e an şaş e: Dîroka devkî belge an tiştê ku ji wê serdemê maye û rasterast şahidiyê dike ye.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina çavkaniya seretayî ye; dîroka devkî veguhastina bûyerên rabirdûyê ye bi rêya şahidî û çîrokên devkî.', 'Na — ev ravekirina çavkaniya seretayî ye; dîroka devkî veguhastina bûyerên rabirdûyê ye bi rêya şahidî û çîrokên devkî.', 'Hayır — bu tanım çavkaniya seretayî''ye aittir; dîroka devkî, geçmişin tanıklık ve sözlü anlatı yoluyla aktarılmasıdır.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0025
('9f208759-56f6-5e09-9545-1dac1f0df967', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Çavkaniya seretayî belge an tiştê ku ji wê serdemê maye û rasterast şahidiyê dike ye. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Çavkaniya seretayî ew belge an tişt e ku di wê serdemê de hatiye çêkirin; lêkolîner rasterast jê sûd werdigire.', 'Rast e. Çavkaniya seretayî ew belge an tişt e ku di wê serdemê de hatiye çêkirin; lêkolîner rasterast jê sûd werdigire.', 'Doğru. Birincil kaynak, o dönemde üretilmiş belge veya nesnedir; araştırmacı ondan doğrudan yararlanır.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0026
('5ceeb270-16c2-5e08-802b-fecc78459576', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Rast e an şaş e: Koçberî guhertina cihê jiyanê ya bi komî ye ji ber şer, aborî an siyasetê.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Koçberî cihguhertina mirovan e ji ber şer, xizanî an zexta siyasî; ew dikare navxweyî an derveyî welat be.', 'Rast e. Koçberî cihguhertina mirovan e ji ber şer, xizanî an zexta siyasî; ew dikare navxweyî an derveyî welat be.', 'Doğru. Göç, savaş, yoksulluk ya da siyasi baskı yüzünden insanların yer değiştirmesidir; ülke içi ya da ülke dışı olabilir.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_dir_0028
('f62e3b6f-c5d1-57d7-b90a-4542ba5b58e7', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Hejmara yekem a "Rojnameya Kurdistan" (1898) li kîjan bajarî derket?', 'Şam', 'Stenbol', 'Bexda', 'Qahîre', 'D', 'Rojnameya Kurdistan a ku Mîqdat Mîdhad Bedirxan derxist, di 1898an de li Qahîreyê hat çapkirin û wek rojnameya kurdî ya yekem tê hesibandin. Paşê hejmarên wê li bajarên din jî derketin.', 'Rojnameya Kurdistan a ku Mîqdat Mîdhad Bedirxan derxist, di 1898an de li Qahîreyê hat çapkirin û wek rojnameya kurdî ya yekem tê hesibandin. Paşê hejmarên wê li bajarên din jî derketin.', 'Mîqdat Mîdhad Bedirxan''ın çıkardığı Rojnameya Kurdistan 1898''de Kahire''de basıldı ve ilk Kürt gazetesi sayılır. Sonraki sayıları başka şehirlerde de çıktı.', 3, true, 'multiple_choice', NULL, NULL, 'Bankanın kendi onaylı tanımlarından türetildi', 'internal:restore_batch_2026_08_07 — terim tanımları editorial/offline bankalarındaki onaylı açıklamalarla aynı', 'approved', 'Kurmancî', 1, now()), -- yerel: restore_2026_08_07_0005
